SET NAMES utf8mb4;
UPDATE email_templates SET
  name='Client Portal · Ερωτηματολόγιο, Συμφωνητικό & Invoice',
  purpose='Μία ενιαία αποστολή του ιδιωτικού client portal με ερωτηματολόγιο, συμφωνητικό και invoice.',
  subject='Τα επόμενα βήματα της συνεργασίας μας',
  body_text='Καλησπέρα σας {{couple_names}},\n\nΕλπίζω να είστε καλά.\n\nΚαθώς προχωράμε στα επόμενα βήματα της συνεργασίας μας, έχω ετοιμάσει το προσωπικό σας Client Portal, όπου θα βρείτε συγκεντρωμένα όλα όσα χρειαζόμαστε για την οργάνωση της συνεργασίας μας.\n\nΜέσα στο portal θα βρείτε:\n\n• Το Ερωτηματολόγιο Γάμου, ώστε να γνωρίσω καλύτερα το πρόγραμμά σας, τις λεπτομέρειες της ημέρας και όλα όσα έχουν ιδιαίτερη σημασία για εσάς.\n\n• Το Συμφωνητικό Συνεργασίας. Παρακαλώ αφιερώστε λίγο χρόνο για να το διαβάσετε προσεκτικά και να επιβεβαιώσετε ότι όλα είναι όπως τα έχουμε συμφωνήσει.\n\n• Το Invoice της προκαταβολής και την ενημερωμένη οικονομική εικόνα της συνεργασίας μας. Μόλις ολοκληρωθεί η απαιτούμενη πληρωμή, η ημερομηνία σας θα δεσμευτεί οριστικά στο ημερολόγιό μου.\n\nΜπορείτε να ανοίξετε το προσωπικό σας portal εδώ:\n\n{{portal_url}}\n\nΔεν χρειάζεται να βιαστείτε. Συμπληρώστε το ερωτηματολόγιο και μελετήστε τα έγγραφα όταν σας εξυπηρετεί. Μόλις λάβω τις απαντήσεις και τις ενημερώσεις σας, θα τα εξετάσω προσεκτικά και θα είμαστε σε επικοινωνία για οτιδήποτε χρειαστεί.\n\nΑν προκύψει οποιαδήποτε απορία ή χρειάζεται κάποια διευκρίνιση, είμαι πάντα στη διάθεσή σας.\n\nΣας ευχαριστώ και πάλι για την εμπιστοσύνη σας. Ανυπομονώ να συνεχίσουμε την προετοιμασία αυτής της τόσο ξεχωριστής ημέρας.\n\nΜε εκτίμηση,\nΒασίλης Μούμκας',
  body_html='<p>Καλησπέρα σας {{couple_names}},</p><p>Ελπίζω να είστε καλά.</p><p>Καθώς προχωράμε στα επόμενα βήματα της συνεργασίας μας, έχω ετοιμάσει το προσωπικό σας <strong>Client Portal</strong>, όπου θα βρείτε συγκεντρωμένα όλα όσα χρειαζόμαστε για την οργάνωση της συνεργασίας μας.</p><p>Μέσα στο portal θα βρείτε:</p><ul><li><strong>Το Ερωτηματολόγιο Γάμου</strong>, ώστε να γνωρίσω καλύτερα το πρόγραμμά σας, τις λεπτομέρειες της ημέρας και όλα όσα έχουν ιδιαίτερη σημασία για εσάς.</li><li><strong>Το Συμφωνητικό Συνεργασίας</strong>. Παρακαλώ αφιερώστε λίγο χρόνο για να το διαβάσετε προσεκτικά και να επιβεβαιώσετε ότι όλα είναι όπως τα έχουμε συμφωνήσει.</li><li><strong>Το Invoice της προκαταβολής</strong> και την ενημερωμένη οικονομική εικόνα της συνεργασίας μας. Μόλις ολοκληρωθεί η απαιτούμενη πληρωμή, η ημερομηνία σας θα δεσμευτεί οριστικά στο ημερολόγιό μου.</li></ul><p>Μπορείτε να ανοίξετε το προσωπικό σας portal εδώ:</p><p><a href="{{portal_url}}" style="display:inline-block;background:#221f20;color:#ffffff;padding:14px 22px;text-decoration:none">Ανοιγμα Client Portal</a></p><p>Δεν χρειάζεται να βιαστείτε. Συμπληρώστε το ερωτηματολόγιο και μελετήστε τα έγγραφα όταν σας εξυπηρετεί. Μόλις λάβω τις απαντήσεις και τις ενημερώσεις σας, θα τα εξετάσω προσεκτικά και θα είμαστε σε επικοινωνία για οτιδήποτε χρειαστεί.</p><p>Αν προκύψει οποιαδήποτε απορία ή χρειάζεται κάποια διευκρίνιση, είμαι πάντα στη διάθεσή σας.</p><p>Σας ευχαριστώ και πάλι για την εμπιστοσύνη σας. Ανυπομονώ να συνεχίσουμε την προετοιμασία αυτής της τόσο ξεχωριστής ημέρας.</p><p>Με εκτίμηση,<br>Βασίλης Μούμκας</p>',
  allowed_placeholders=JSON_ARRAY('couple_names','portal_url'),
  trigger_description='Send once after offer acceptance. The single portal contains questionnaire, agreement and invoice.',
  is_active=1,
  version=version+1
WHERE id='005';

UPDATE email_templates SET is_active=0,version=version+1 WHERE id IN ('006','007');
